-- Termos de embargo do IBAMA (CSV dos dados abertos) como ESPELHO VERSIONADO: vetorial.ibama_embargos. Idempotente.
-- Rodar como postgres (o etl so tem DML):
--   .\infra\scripts\dw.ps1 psql -Arquivo ibama\embargos\sql\01_tabela.sql
--
-- Regras (as mesmas do SICAR, do PRODES, do MapBiomas Alerta, da FUNAI e do DETER): a tabela espelha o que o IBAMA publica hoje; cada
-- embargo (chave_tad) tem versoes (vigente_desde/vigente_ate); embargo que a fonte deixa de publicar tem a versao FECHADA (nada e apagado na
-- coleta); embargo que some e volta IDENTICO tem a versao reaberta. Colunas com os nomes da fonte em minusculas; texto sempre `text`.
-- A fonte nao tem identificador unico simples: a chave e (NUM_TAD, SER_TAD, SEQ_TAD), reunida em chave_tad.
--
-- DADO PESSOAL (decisao do usuario, 2026-10-26): entra tudo como a fonte publica, exceto o CPF de pessoa fisica, que vai so como hash
-- (cpf_embargado_hash). O IBAMA publica nome e CPF/CNPJ completos; ver LEIAME_embargos.md.

INSERT INTO dim.fontes (nome, sigla, url, descricao)
SELECT 'IBAMA', 'IBAMA', 'https://dadosabertos.ibama.gov.br', 'Instituto Brasileiro do Meio Ambiente e dos Recursos Naturais Renovaveis - dados abertos (termos de embargo)'
WHERE NOT EXISTS (SELECT 1 FROM dim.fontes WHERE nome = 'IBAMA');

CREATE TABLE IF NOT EXISTS vetorial.ibama_embargos (
    id                            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    chave_tad                     text        NOT NULL,         -- derivado: num_tad|ser_tad|seq_tad (a fonte nao traz identificador unico; os tres juntos sao unicos)
    seq_tad                       bigint,                       -- fonte: SEQ_TAD (vazio em ~3 mil termos)
    des_status_formulario         text,                         -- fonte: DES_STATUS_FORMULARIO (Lavrado, Cancelado, Excluido, Substituido por outro)
    des_status_formulario_aie     text,                         -- fonte: DES_STATUS_FORMULARIO_AIE
    sit_cancelado                 text,                         -- fonte: SIT_CANCELADO (S/N)
    num_tad                       text,                         -- fonte: NUM_TAD (numero do termo; texto: ha numeros alfanumericos)
    ser_tad                       text,                         -- fonte: SER_TAD (serie do termo)
    cod_substituicao              text,                         -- fonte: COD_SUBSTITUICAO
    dat_embargo                   timestamp,                    -- fonte: DAT_EMBARGO (sem fuso). Ver data_embargo_suspeita
    dat_impressao                 timestamp,                    -- fonte: DAT_IMPRESSAO
    forma_entrega                 text,                         -- fonte: FORMA_ENTREGA
    num_pessoa_embargo            bigint,                       -- fonte: NUM_PESSOA_EMBARGO (codigo interno do IBAMA para a pessoa embargada)
    nome_embargado                text,                         -- fonte: NOME_EMBARGADO (como o IBAMA publica)
    cpf_cnpj_embargado            text,                         -- fonte: CPF_CNPJ_EMBARGADO, SO quando NAO e CPF (CNPJ e outros); CPF de pessoa fisica NAO e guardado aqui
    tipo_doc_embargado            text,                         -- derivado: 'CPF' (11 digitos), 'CNPJ' (14) ou 'OUTRO'; NULL se a fonte nao traz o documento
    cpf_embargado_hash            text,                         -- derivado: HMAC-SHA256 (hex) do CPF de 11 digitos, com chave fora do banco
    num_processo                  text,                         -- fonte: NUM_PROCESSO
    des_tad                       text,                         -- fonte: DES_TAD (texto do termo)
    cod_municipio                 text,                         -- fonte: COD_MUNICIPIO (IBGE; 2 linhas vem com 6 digitos)
    municipio                     text,                         -- fonte: MUNICIPIO
    uf                            text,                         -- fonte: UF
    id_estado                     smallint REFERENCES dim.estados (id_estado),    -- derivado de uf
    id_municipio                  integer,                      -- derivado de cod_municipio (dim.municipios); NULL se nao casar
    des_localizacao               text,                         -- fonte: DES_LOCALIZACAO
    num_longitude_tad             double precision,             -- fonte: NUM_LONGITUDE_TAD (ponto do termo; vazio em ~15%; ~300 latitudes fora do Brasil)
    num_latitude_tad              double precision,             -- fonte: NUM_LATITUDE_TAD
    deter_prodes                  text,                         -- fonte: DETER_PRODES (Deter/Prodes: o embargo foi ligado a um poligono de desmatamento)
    id_poligono                   numeric,                      -- fonte: ID_POLIGONO (do alerta DETER ou do PRODES)
    embarga_poligono              text,                         -- fonte: EMBARGA_POLIGONO (S/N)
    qtd_area_embargada            numeric,                      -- fonte: QTD_AREA_EMBARGADA (hectares; virgula decimal na origem)
    nome_imovel                   text,                         -- fonte: NOME_IMOVEL
    tipo_area                     text,                         -- fonte: TIPO_AREA (Desmatamento, Atividade, Queimada, Outros...)
    dat_ult_alter_geom            timestamp,                    -- fonte: DAT_ULT_ALTER_GEOM
    unid_apresentacao             text,                         -- fonte: UNID_APRESENTACAO
    unid_controle                 text,                         -- fonte: UNID_CONTROLE
    sit_desembargo                text,                         -- fonte: SIT_DESEMBARGO (S = desembargado)
    tipo_desembargo               text,                         -- fonte: TIPO_DESEMBARGO (Administrativo, Judicial)
    dat_desembargo                timestamp,                    -- fonte: DAT_DESEMBARGO
    des_desembargo                text,                         -- fonte: DES_DESEMBARGO
    seq_auto_infracao             bigint,                       -- fonte: SEQ_AUTO_INFRACAO
    num_auto_infracao             text,                         -- fonte: NUM_AUTO_INFRACAO
    seq_notificacao               bigint,                       -- fonte: SEQ_NOTIFICACAO
    seq_acao_fiscalizatoria       bigint,                       -- fonte: SEQ_ACAO_FISCALIZATORIA
    cd_acao_fiscalizatoria        text,                         -- fonte: CD_ACAO_FISCALIZATORIA
    operacao                      text,                         -- fonte: OPERACAO
    seq_ordem_fiscalizacao        bigint,                       -- fonte: SEQ_ORDEM_FISCALIZACAO
    ordem_fiscalizacao            text,                         -- fonte: ORDEM_FISCALIZACAO
    unid_ordenadora               text,                         -- fonte: UNID_ORDENADORA
    seq_solicitacao_recurso       bigint,                       -- fonte: SEQ_SOLICITACAO_RECURSO
    solicitacao_recurso           text,                         -- fonte: SOLICITACAO_RECURSO
    operacao_sol_recurso          text,                         -- fonte: OPERACAO_SOL_RECURSO
    dat_ult_alteracao             timestamp,                    -- fonte: DAT_ULT_ALTERACAO
    tipo_alteracao                text,                         -- fonte: TIPO_ALTERACAO
    justificativa_alteracao       text,                         -- fonte: JUSTIFICATIVA_ALTERACAO
    ultima_atualizacao_relatorio  timestamp,                    -- fonte: ULTIMA_ATUALIZACAO_RELATORIO (hora em que o IBAMA gerou o CSV; muda todo dia e NAO entra na comparacao)
    data_embargo_suspeita         boolean     NOT NULL DEFAULT false,   -- derivado: dat_embargo no futuro ou antes de 1989 (erro de digitacao na fonte); o valor NAO e corrigido
    geom                          geometry(MultiPolygon, 4674), -- fonte: GEOM_AREA_EMBARGADA (WKT; so ~51% dos termos tem poligono). NULL quando ausente ou geom_anomala
    geom_ponto                    geometry(Point, 4674) GENERATED ALWAYS AS (
                                      CASE WHEN num_longitude_tad IS NOT NULL AND num_latitude_tad IS NOT NULL
                                           THEN ST_SetSRID(ST_MakePoint(num_longitude_tad, num_latitude_tad), 4674) END) STORED,   -- derivado do ponto lat/lon do termo
    geom_anomala                  boolean     NOT NULL DEFAULT false,
    geom_origem_texto             text,
    id_fonte                      smallint    NOT NULL REFERENCES dim.fontes (id_fonte),
    importado_em                  date        NOT NULL DEFAULT current_date,
    vigente_desde                 date        NOT NULL DEFAULT current_date,
    vigente_ate                   date,
    coletado_em                   timestamptz NOT NULL DEFAULT now(),
    reaberto_em                   date
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_ibama_embargos_vigente ON vetorial.ibama_embargos (chave_tad) WHERE vigente_ate IS NULL;
-- Indices secundarios (apos a primeira carga eles ja existem: IF NOT EXISTS deixa reaplicar)
CREATE INDEX IF NOT EXISTS ix_ibama_embargos_geom       ON vetorial.ibama_embargos USING gist (geom)       WHERE vigente_ate IS NULL;
CREATE INDEX IF NOT EXISTS ix_ibama_embargos_geom_ponto ON vetorial.ibama_embargos USING gist (geom_ponto) WHERE vigente_ate IS NULL;
CREATE INDEX IF NOT EXISTS ix_ibama_embargos_data       ON vetorial.ibama_embargos (dat_embargo)           WHERE vigente_ate IS NULL;
CREATE INDEX IF NOT EXISTS ix_ibama_embargos_uf         ON vetorial.ibama_embargos (id_estado)             WHERE vigente_ate IS NULL;
CREATE INDEX IF NOT EXISTS ix_ibama_embargos_pessoa     ON vetorial.ibama_embargos (num_pessoa_embargo)    WHERE vigente_ate IS NULL;
CREATE INDEX IF NOT EXISTS ix_ibama_embargos_cpf_hash   ON vetorial.ibama_embargos (cpf_embargado_hash)    WHERE vigente_ate IS NULL AND cpf_embargado_hash IS NOT NULL;

COMMENT ON TABLE vetorial.ibama_embargos IS
    'Termos de embargo do IBAMA (CSV dos dados abertos, regerado diariamente). Espelho versionado: vigente = vigente_ate IS NULL. Contem nome do embargado e CNPJ como o IBAMA publica; o CPF de pessoa fisica so como hash. Ver ibama/embargos/LEIAME_embargos.md.';
COMMENT ON COLUMN vetorial.ibama_embargos.chave_tad IS 'Derivado: num_tad|ser_tad|seq_tad. A fonte nao tem identificador unico (num_tad+ser_tad repete 325 vezes; seq_tad vem vazio em ~3 mil); os tres juntos sao unicos.';
COMMENT ON COLUMN vetorial.ibama_embargos.cpf_cnpj_embargado IS 'Origem: CPF_CNPJ_EMBARGADO, so quando nao e CPF (CNPJ). O CPF de pessoa fisica NAO e guardado: ver cpf_embargado_hash.';
COMMENT ON COLUMN vetorial.ibama_embargos.cpf_embargado_hash IS 'HMAC-SHA256 (hex) do CPF de 11 digitos com chave secreta fora do banco: permite contar embargos por pessoa sem expor o numero. Se a chave for perdida, o pipeline recria e todos os hashes mudam.';
COMMENT ON COLUMN vetorial.ibama_embargos.data_embargo_suspeita IS 'true = dat_embargo no futuro (ex.: 2925-09-25) ou antes de 1989; erro de digitacao na fonte, o valor nao e corrigido.';
COMMENT ON COLUMN vetorial.ibama_embargos.ultima_atualizacao_relatorio IS 'Origem: ULTIMA_ATUALIZACAO_RELATORIO, hora em que o IBAMA gerou o CSV (igual em todas as linhas e muda todo dia); guardada como veio na versao, nao entra na comparacao.';
COMMENT ON COLUMN vetorial.ibama_embargos.geom IS 'Origem: GEOM_AREA_EMBARGADA (WKT, CRS nao declarado; tratado como SIRGAS 2000). So ~51% dos termos tem poligono; os demais tem so o ponto (geom_ponto).';

INSERT INTO catalogo.mapa_colunas (tabela, coluna, origem, fonte, observacao)
SELECT 'vetorial.ibama_embargos', c.column_name,
       CASE WHEN c.column_name IN ('chave_tad','tipo_doc_embargado','cpf_embargado_hash','id_estado','id_municipio','data_embargo_suspeita','geom_ponto') THEN 'derivado'
            WHEN c.column_name IN ('id','id_fonte','importado_em','vigente_desde','vigente_ate','coletado_em','reaberto_em','geom_anomala','geom_origem_texto') THEN 'controle'
            WHEN c.column_name = 'geom' THEN 'GEOM_AREA_EMBARGADA'
            ELSE upper(c.column_name) END,
       CASE WHEN c.column_name IN ('chave_tad','tipo_doc_embargado','cpf_embargado_hash','data_embargo_suspeita','geom_ponto','id','id_fonte','importado_em',
                                   'vigente_desde','vigente_ate','coletado_em','reaberto_em','geom_anomala') THEN 'pipeline'
            WHEN c.column_name = 'id_estado' THEN 'dim.estados' WHEN c.column_name = 'id_municipio' THEN 'dim.municipios' ELSE 'IBAMA' END,
       NULL
FROM information_schema.columns c
WHERE c.table_schema = 'vetorial' AND c.table_name = 'ibama_embargos'
ON CONFLICT (tabela, coluna) DO UPDATE SET origem = EXCLUDED.origem, fonte = EXCLUDED.fonte;

GRANT SELECT, INSERT, UPDATE, DELETE ON vetorial.ibama_embargos TO etl;      -- DELETE: so para a rotina de retencao
GRANT SELECT ON vetorial.ibama_embargos TO leitura, geoserver, analistas;
GRANT MAINTAIN ON vetorial.ibama_embargos TO etl;

SELECT 'vetorial.ibama_embargos' AS item, count(*)::text AS valor FROM vetorial.ibama_embargos;
